<script setup>
import { computed, onMounted, ref } from 'vue'
import { RouterLink } from 'vue-router'
import api from '../api'

const activeTab = ref('pending'); const searchQuery = ref(''); const sidebarOpen = ref(false); const allClaims = ref([]); const isLoading = ref(false)
const pendingClaims = computed(() => allClaims.value.filter((claim) => claim.status === 'under_review'))
const approvedClaims = computed(() => allClaims.value.filter((claim) => claim.status === 'approved'))
const matches = (claim) => { const q = searchQuery.value.toLowerCase(); return !q || claim.item_name?.toLowerCase().includes(q) || claim.claimant_name?.toLowerCase().includes(q) }
const filteredPending = computed(() => pendingClaims.value.filter(matches)); const filteredApproved = computed(() => approvedClaims.value.filter(matches))
const loadClaims = async () => { isLoading.value = true; try { allClaims.value = (await api.get('/claims')).data } catch { allClaims.value = [] } finally { isLoading.value = false } }
const approveClaim = async (id) => { try { await api.put(`/claims/${id}/approve`, {}); loadClaims() } catch {} }
const rejectClaim = async (id) => { try { await api.put(`/claims/${id}/reject`, {}); loadClaims() } catch {} }
onMounted(loadClaims)
</script>

<template>
  <div class="cm-wrapper"><div v-if="sidebarOpen" class="overlay" @click="sidebarOpen=false"></div><div class="sidebar" :class="{open:sidebarOpen}"><div class="sidebar-top"><div class="sidebar-brand"><div class="sidebar-logo">⌂</div><div><p class="sidebar-title">LDCU iFound</p><p class="sidebar-sub">Lost &amp; Found System</p></div></div><button class="close-btn" @click="sidebarOpen=false">✕</button></div><nav class="sidebar-nav"><RouterLink to="/dashboard" class="nav-item">Dashboard</RouterLink><RouterLink to="/lost-and-found" class="nav-item">Lost &amp; Found</RouterLink><RouterLink to="/claims" class="nav-item active">Claims Management</RouterLink><RouterLink to="/history" class="nav-item">Claimed History</RouterLink><RouterLink to="/messages" class="nav-item">Messages</RouterLink><RouterLink to="/post-item" class="nav-item">Post Item</RouterLink><RouterLink to="/profile" class="nav-item">My Profile</RouterLink></nav><div class="sidebar-footer">© 2025 LDCU iFound System</div></div><div class="main"><div class="topbar"><button class="menu-btn" @click="sidebarOpen=!sidebarOpen">☰</button><div class="topbar-brand"><div class="topbar-logo">⌂</div><div><p class="topbar-name">LDCU iFound</p><p class="topbar-sub">Lost &amp; Found System</p></div></div></div><div class="content"><div class="page-header"><h2>Claims Management</h2><p>Review and approve student claims</p></div><div class="tabs"><button class="tab-btn" :class="{'pending-active':activeTab==='pending'}" @click="activeTab='pending'">Pending ({{pendingClaims.length}})</button><button class="tab-btn" :class="{'approved-active':activeTab==='approved'}" @click="activeTab='approved'">Approved ({{approvedClaims.length}})</button></div><div class="search-bar">⌕<input v-model="searchQuery" placeholder="Search claims..." /></div><div v-if="isLoading" class="loading">Loading claims...</div><div v-else class="table-wrapper"><table><thead><tr><th>Image</th><th>Item Name</th><th>Student Name</th><th>Request Date</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="claim in (activeTab==='pending'?filteredPending:filteredApproved)" :key="claim.id"><td><img :src="claim.image_url || 'https://images.unsplash.com/photo-1553062407-98eeb64c6a62?w=100&q=80'" :alt="claim.item_name" class="item-thumb" /></td><td class="item-name-cell">{{claim.item_name}}</td><td>{{claim.claimant_name}}</td><td>{{claim.request_date}}</td><td><span class="status-badge" :class="activeTab==='pending'?'under-review':'approved'">{{activeTab==='pending'?'Under Review':'Approved'}}</span></td><td><div v-if="activeTab==='pending'" class="action-btns"><button class="btn-approve" @click="approveClaim(claim.id)">✓</button><button class="btn-reject" @click="rejectClaim(claim.id)">×</button></div></td></tr><tr v-if="(activeTab==='pending'?filteredPending:filteredApproved).length===0"><td colspan="6" class="empty">No {{activeTab}} claims</td></tr></tbody></table></div></div></div></div>
</template>

<style scoped>
