d-active{background:#22c55e;color:#fff;border-color:#22c55e}.search-bar{display:flex;gap:10px;background:#fff;border:1.5px solid #dde1e9;border-radius:10px;padding:10px 16px;margin-bottom:20px}.search-bar input{border:0;outline:0;flex:1}.loading{text-align:center;padding:60px}.table-wrapper{background:#fff;border-radius:14px;overflow:auto;box-shadow:0 1px 4px rgba(0,0,0,.06)}table{width:100%;border-collapse:collapse}thead tr{background:#0d1b2e}th{padding:14px 16px;text-align:left;color:#fff;font-size:.85rem}td{padding:14px 16px;border-bottom:1px solid #f0f0f0;color:#333;font-size:.88rem}.item-thumb{width:52px;height:52px;object-fit:cover;border-radius:8px}.item-name-cell{font-weight:700}.status-badge{display:inline-block;padding:5px 14px;border-radius:20px;font-size:.82rem;font-weight:600}.under-review{background:#fef9c3;color:#ca8a04}.approved{background:#dcfce7;color:#16a34a}.action-btns{display:flex;gap:8px}.btn-approve,.btn-reject{width:34px;height:34px;border:0;border-radius:8px;color:#fff;cursor:pointer}.btn-approve{background:#22c55e}.btn-reject{background:#ef4444}.empty{text-align:center;color:#888}
